use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_until_success_and_records_delays() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 8,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 | 2 | 3 => Err(RetryError::Transient("try again".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![5, 8, 8]);
}

#[test]
fn public_api_returns_last_transient_error_at_attempt_limit() {
    let config = RetryConfig {
        max_attempts: 2,
        base_delay_ms: 1,
        max_delay_ms: 1,
    };
    let mut sleeper = FakeSleeper::default();

    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
    assert_eq!(sleeper.sleeps, vec![1]);
}

