 }

 impl RetryConfig {
-    // TODO(retry-policy): delay growth must saturate at `max_delay_ms`.
+    /// Returns the delay for a retry number (where the first retry is zero).
+    /// Multiplication is checked so very large retry numbers cannot overflow.
+    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
+        let max_delay = self.max_delay_ms;
+        let mut result = self.base_delay_ms.min(max_delay);
+        let mut factor = 2u64;
+        let mut exponent = retry_number;
+
+        // Exponentiation by squaring keeps even extreme attempt numbers cheap.
+        while exponent != 0 && result < max_delay {
+            if exponent & 1 == 1 {
+                result = result.saturating_mul(factor).min(max_delay);
+            }
+            exponent >>= 1;
+            factor = factor.saturating_mul(factor);
+        }
+        result
+    }
